"use client";

import Link from "next/link";
import { useEffect, useRef } from "react";
import { PDF_SIZE, PDF_URL } from "@/lib/book";
import type { BookInfo } from "@/lib/flipbook";

// Self-hosted flipbook for the memorial book. Page images come from
// public/book/pages (generated by `npm run book`). Behaviour lives in
// src/lib/flipbook.ts, which builds the pages and owns the toolbar state.

const icon = {
  prev: '<path d="M15 18l-6-6 6-6"/>',
  next: '<path d="M9 18l6-6-6-6"/>',
  back: '<path d="M10 18l-6-6 6-6M4 12h16"/>',
  zoomIn: '<circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3M11 8v6M8 11h6"/>',
  zoomOut: '<circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3M8 11h6"/>',
  full: '<path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/>',
  exitFull: '<path d="M9 4v5H4M15 4v5h5M9 20v-5H4M15 20v-5h5"/>',
  soundOff: '<path d="M11 5 6 9H3v6h3l5 4V5z"/><path d="M22 9l-6 6M16 9l6 6"/>',
  soundOn: '<path d="M11 5 6 9H3v6h3l5 4V5z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/>',
  download: '<path d="M12 4v11M7 10l5 5 5-5M5 20h14"/>',
  window: '<path d="M14 4h6v6M20 4l-8 8M18 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5"/>',
};
// Fullscreen and sound swap icons from their data attributes, so icons are markup strings.
const svg = (d: string) =>
  `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
const html = (d: string) => ({ __html: svg(d) });

export default function BookReader({ standalone = false, pageCount, pageWidth, pageHeight }: BookInfo & { standalone?: boolean }) {
  const readerRef = useRef<HTMLElement>(null);

  useEffect(() => {
    let destroy: (() => void) | undefined;
    let cancelled = false;
    import("@/lib/flipbook").then(({ initFlipbook }) => {
      if (!cancelled && readerRef.current) destroy = initFlipbook(readerRef.current, { pageCount, pageWidth, pageHeight });
    });
    return () => {
      cancelled = true;
      destroy?.();
    };
  }, [pageCount, pageWidth, pageHeight]);

  return (
    <section ref={readerRef} className={standalone ? "reader standalone" : "reader"} data-reader aria-label="Memorial book reader">
      <div className="reader-stage" data-stage>
        {/* The page-flip book is inserted here by flipbook.ts. */}
        <div className="zoom-view" data-zoom-view hidden tabIndex={0} aria-label="Zoomed page view. Use arrow keys or drag to move around." />
        <noscript>
          <div className="reader-noscript">
            <p>The page-turning reader needs JavaScript. You can still read the full memorial book as a PDF.</p>
            <a className="button gold" href={PDF_URL}>
              Open the PDF ({PDF_SIZE})
            </a>
          </div>
        </noscript>
      </div>

      <div className="reader-toolbar" role="toolbar" aria-label="Book controls">
        <div className="tb-group">
          <button type="button" className="tb-btn" data-action="prev" aria-label="Previous page" dangerouslySetInnerHTML={html(icon.prev)} />
          <form className="page-jump" data-jump>
            <label htmlFor="page-input" className="visually-hidden">
              Go to page
            </label>
            <input id="page-input" type="number" inputMode="numeric" min={1} max={pageCount} defaultValue={1} data-page-input />
            <span className="page-total" data-page-label aria-hidden="true">
              of {pageCount}
            </span>
            <button type="submit" className="visually-hidden">
              Go
            </button>
          </form>
          <button type="button" className="tb-btn" data-action="next" aria-label="Next page" dangerouslySetInnerHTML={html(icon.next)} />
        </div>
        <div className="tb-group">
          <button type="button" className="tb-btn" data-action="zoom-out" aria-label="Zoom out" disabled dangerouslySetInnerHTML={html(icon.zoomOut)} />
          <span className="zoom-level" data-zoom-label aria-hidden="true">
            100%
          </span>
          <button type="button" className="tb-btn" data-action="zoom-in" aria-label="Zoom in" dangerouslySetInnerHTML={html(icon.zoomIn)} />
          <button
            type="button"
            className="tb-btn"
            data-action="fullscreen"
            aria-label="Full screen"
            aria-pressed="false"
            data-icon-on={svg(icon.exitFull)}
            data-icon-off={svg(icon.full)}
            dangerouslySetInnerHTML={html(icon.full)}
          />
          <button
            type="button"
            className="tb-btn"
            data-action="sound"
            aria-label="Page-turn sound"
            aria-pressed="false"
            data-icon-on={svg(icon.soundOn)}
            data-icon-off={svg(icon.soundOff)}
            dangerouslySetInnerHTML={html(icon.soundOff)}
          />
          {standalone ? (
            <Link className="tb-btn" href="/memorial-book" aria-label="Back to berniceoffei.com" title="Back to berniceoffei.com" dangerouslySetInnerHTML={html(icon.back)} />
          ) : (
            <a className="tb-btn" href="/memorial-book/reader" target="_blank" rel="noopener" aria-label="Open the reader in a new window" title="Open in new window" dangerouslySetInnerHTML={html(icon.window)} />
          )}
          <a className="tb-btn" href={PDF_URL} download aria-label={`Download PDF (${PDF_SIZE})`} title="Download PDF" dangerouslySetInnerHTML={html(icon.download)} />
        </div>
      </div>
      <p className="visually-hidden" aria-live="polite" data-announcer />
    </section>
  );
}
